    DECLARE @NewArticles NVARCHAR(MAX) = N'[
      {"branch":"buying","topic":"tools","area":"electrical","readMinutes":5,"article":{"slug":"choosing-clamp-meter","category":"راهنمای خرید","kicker":"راهنمای خرید تجهیزات اندازه‌گیری","title":"راهنمای انتخاب آمپرمتر انبری برای کارگاه","summary":"دهانهٔ فک، نوع جریان، رنج اندازه‌گیری و ایمنی را پیش از خرید آمپرمتر انبری با نوع کارتان هماهنگ کنید.","author":"تحریریه ندا اولیائی","publishedAt":"۱۴۰۵/۰۸/۰۱","readTime":"۵ دقیقه مطالعه","heroImage":"content/products/images/main/digital-clamp-meter-hn-009-row-009-main.webp","contentImage":"content/products/images/main/digital-clamp-meter-hn-009-row-009-main.webp","lead":"آمپرمتر انبری اندازه‌گیری جریان را بدون بازکردن مدار ممکن می‌کند؛ البته فقط وقتی ابزار و روش استفاده با مدار موردنظر سازگار باشد.","sections":[{"id":"section-1","title":"جریان مورد اندازه‌گیری را مشخص کنید","content":"برای شروع، مشخص کنید بیشتر با جریان متناوب سروکار دارید یا مستقیم. همهٔ مدل‌ها هر دو نوع را اندازه نمی‌گیرند. رنج اندازه‌گیری را هم از روی جریان معمول و بیشینهٔ مدار انتخاب کنید تا هم خوانایی مناسبی داشته باشید و هم ابزار خارج از محدوده کار نکند."},{"id":"section-2","title":"دهانه و شکل فک را بسنجید","content":"قطر کابل یا شینه‌ای را که باید داخل فک قرار بگیرد اندازه بگیرید. دهانهٔ بزرگ‌تر همیشه انتخاب بهتر نیست؛ فک باید به‌درستی بسته شود و فقط یک هادی از آن عبور کند. عبور هم‌زمان رفت و برگشت معمولاً میدان‌ها را خنثی می‌کند و عدد گمراه‌کننده می‌دهد."},{"id":"section-3","title":"امکانات را بر پایهٔ کار انتخاب کنید","content":"برای عیب‌یابی ممکن است اندازه‌گیری ولتاژ، مقاومت، پیوستگی یا جریان هجومی هم لازم شود. قابلیت نگه‌داشتن عدد و نور نمایشگر در محیط کم‌نور کاربردی است؛ اما دقت، وضوح نمایش و مشخصات واقعی هر رنج را از دفترچهٔ همان مدل بخوانید."},{"id":"section-4","title":"ایمنی را مقدم بدانید","content":"ردهٔ اندازه‌گیری و ولتاژ مجاز باید برای محل کار مناسب باشد و پراب‌ها، بدنه و درپوش باتری سالم باشند. پیش از نزدیک‌شدن به مدار زنده، دستورالعمل سازنده و روش ایمن محل کار را رعایت کنید؛ آمپرمتر انبری جایگزین آموزش یا تجهیزات حفاظت فردی نیست."}],"conclusion":"مدلی انتخاب کنید که نوع جریان، ظرفیت فک، محدودهٔ اندازه‌گیری و ردهٔ ایمنی آن با کاربرد واقعی‌تان منطبق باشد. برای مدار برق‌دار، ارزیابی صلاحیت کاربر و روش ایمن از هر قابلیت اضافه‌ای مهم‌تر است.","sources":[],"tags":[{"label":"آمپرمتر انبری","filter":"area-electrical"},{"label":"ابزار اندازه‌گیری","filter":"area-electrical"}],"relatedArticles":[],"metrics":{"views":0,"likes":0,"averageRating":0,"comments":0}}},
      {"branch":"education","topic":"tools","area":"electrical","readMinutes":5,"article":{"slug":"multimeter-probe-safety","category":"آموزش تخصصی","kicker":"دانش فنی اندازه‌گیری","title":"پراب مولتی‌متر را ایمن و درست استفاده کنید","summary":"انتخاب ورودی، سلامت عایق و ترتیب اندازه‌گیری پراب‌ها، سه نکتهٔ ساده برای کاهش خطای کار با مولتی‌متر هستند.","author":"تحریریه ندا اولیائی","publishedAt":"۱۴۰۵/۰۸/۰۲","readTime":"۵ دقیقه مطالعه","heroImage":"content/products/images/main/electrical-installation-digital-multimeter-hn-010-row-010-main.webp","contentImage":"content/products/images/main/electrical-installation-digital-multimeter-hn-010-row-010-main.webp","lead":"بخش بزرگی از خطاهای اندازه‌گیری از انتخاب اشتباه ورودی یا پراب آسیب‌دیده می‌آید؛ بررسی کوتاه پیش از کار، جلوی بسیاری از این خطاها را می‌گیرد.","sections":[{"id":"section-1","title":"ورودی را با کمیت هماهنگ کنید","content":"برای ولتاژ و مقاومت، سیم‌ها باید در ورودی‌های تعریف‌شدهٔ همان مولتی‌متر باشند. اندازه‌گیری جریان مسیر دیگری دارد و اتصال اشتباه می‌تواند اتصال کوتاه ایجاد کند. پیش از هر تغییر، دستگاه را از مدار جدا و دفترچهٔ مدل را بررسی کنید."},{"id":"section-2","title":"عایق و نوک پراب را بازبینی کنید","content":"ترک، بریدگی، شل‌شدن اتصال یا نمایان‌شدن فلز در محل نامناسب نشانهٔ توقف استفاده است. پراب جایگزین باید از نظر رده و ولتاژ با دستگاه سازگار باشد. انگشتان را پشت محافظ پراب نگه دارید و از لمس بخش رسانا بپرهیزید."},{"id":"section-3","title":"ترتیب سنجش را رعایت کنید","content":"نوع اندازه‌گیری و وضعیت کلید را پیش از اتصال کنترل کنید. برای مقاومت یا پیوستگی، مدار باید بی‌برق باشد و انرژی ذخیره‌شدهٔ خازن‌ها نیز طبق روش ایمن تخلیه شود. پس از کار، پراب‌ها را از مدار جدا و سپس به ورودی مناسب برگردانید."},{"id":"section-4","title":"محدودیت ابزار را بشناسید","content":"عدد نمایشگر به‌تنهایی تضمین نمی‌کند که سنجش ایمن یا دقیق بوده است. ردهٔ اندازه‌گیری، محدودهٔ مجاز، شرایط محیط و سلامت فیوز داخلی را در راهنمای سازنده ببینید. در کار تخصصی، دستورالعمل محل کار و آموزش معتبر را مبنا قرار دهید."}],"conclusion":"پیش از هر سنجش، ورودی و وضعیت دستگاه را بررسی کنید، از پراب سالم و سازگار استفاده کنید و فقط در محدودهٔ مجاز ابزار کار کنید.","sources":[],"tags":[{"label":"مولتی‌متر","filter":"area-electrical"},{"label":"ایمنی","filter":"safety"}],"relatedArticles":[],"metrics":{"views":0,"likes":0,"averageRating":0,"comments":0}}},
      {"branch":"buying","topic":"tools","area":"tools","readMinutes":5,"article":{"slug":"choosing-insulated-screwdrivers","category":"راهنمای خرید","kicker":"انتخاب ابزار دستی","title":"پیچ‌گوشتی عایق‌دار مناسب کار برق را چطور انتخاب کنیم؟","summary":"نوع نوک، کیفیت ساخت، اندازه و مشخصات عایقی را متناسب با کار و استاندارد موردنیاز بررسی کنید.","author":"تحریریه ندا اولیائی","publishedAt":"۱۴۰۵/۰۸/۰۳","readTime":"۵ دقیقه مطالعه","heroImage":"content/products/images/main/insulated-electrician-screwdriver-set-hn-021-row-021-main.webp","contentImage":"content/products/images/main/insulated-electrician-screwdriver-set-hn-021-row-021-main.webp","lead":"پیچ‌گوشتی عایق‌دار باید با اتصال موردنظر جور باشد و مشخصات سازندهٔ آن قابل بررسی باشد؛ رنگ دسته به‌تنهایی معیار ایمنی نیست.","sections":[{"id":"section-1","title":"شکل و اندازهٔ نوک را تطبیق دهید","content":"پیش از خرید، شکل پیچ‌های رایج در تجهیزات خود را مشخص کنید؛ چهارسو، دوسو و گونه‌های دیگر جای هم را نمی‌گیرند. نوک نامتناسب به پیچ آسیب می‌زند و احتمال لغزش را بالا می‌برد. طول ساق را هم با عمق محل دسترسی بسنجید."},{"id":"section-2","title":"مشخصات عایق را بررسی کنید","content":"برای کار برقی، فقط مدلی را در نظر بگیرید که سازنده آن را برای کاربرد موردنیاز مشخص کرده و مشخصات مربوط روی ابزار و بسته‌بندی روشن باشد. علامت یا رنگ مشابه به‌تنهایی گواهی کافی نیست؛ اطلاعات فنی و دستورالعمل محصول را بررسی کنید."},{"id":"section-3","title":"کیفیت ساخت و ارگونومی","content":"اتصال ساق به دسته باید محکم باشد و نوک پرداخت یکنواخت داشته باشد. دسته‌ای را انتخاب کنید که در دست شما کنترل خوبی بدهد و برای نیروی لازم مناسب باشد. اگر مجموعه می‌خرید، بررسی کنید سایزهای داخل جعبه واقعاً با پیچ‌های محل کارتان هماهنگ‌اند."},{"id":"section-4","title":"مراقبت پس از خرید","content":"از پیچ‌گوشتی به‌عنوان اهرم یا قلم استفاده نکنید و نوک را با روش غیراصولی سنگ نزنید. پیش از هر استفاده، عایق را از نظر بریدگی، ترک و آلودگی بررسی کنید. ابزار آسیب‌دیده باید از چرخهٔ کار خارج شود و مطابق دستور سازنده جایگزین شود."}],"conclusion":"نوک سازگار، اندازهٔ مناسب، مشخصات فنی قابل پیگیری و عایق سالم معیارهای اصلی‌اند. استفاده از ابزار عایق‌دار نیز جای قطع برق و رعایت روش ایمن کار را نمی‌گیرد.","sources":[],"tags":[{"label":"پیچ‌گوشتی عایق‌دار","filter":"area-tools"},{"label":"ایمنی برق","filter":"safety"}],"relatedArticles":[],"metrics":{"views":0,"likes":0,"averageRating":0,"comments":0}}},
      {"branch":"safety","topic":"tools","area":"electrical","readMinutes":6,"article":{"slug":"electrical-panel-work-checklist","category":"ایمنی و نگهداری","kicker":"چک‌لیست ایمنی کار","title":"پیش از کار روی تابلو برق چه چیزهایی را بررسی کنیم؟","summary":"بررسی محدودهٔ کار، قطع و ایمن‌سازی منبع، ابزار مناسب و کنترل دوباره، پایهٔ یک فرایند ایمن برای تابلو برق است.","author":"تحریریه ندا اولیائی","publishedAt":"۱۴۰۵/۰۸/۰۴","readTime":"۶ دقیقه مطالعه","heroImage":"content/products/images/main/wiring-and-installation-tool-set-hn-024-row-024-main.webp","contentImage":"content/products/images/main/wiring-and-installation-tool-set-hn-024-row-024-main.webp","lead":"کار روی تابلو برق به برنامه‌ریزی و صلاحیت فنی نیاز دارد. این چک‌لیست یادآوری عمومی است و مجوز کار روی مدار زنده محسوب نمی‌شود.","sections":[{"id":"section-1","title":"دامنهٔ کار و خطرها را بشناسید","content":"پیش از بازکردن تابلو، نقشه و محدودهٔ کاری را مشخص کنید و از وجود منابع چندگانه، تغذیهٔ پشتیبان یا انرژی ذخیره‌شده آگاه شوید. اگر مدار یا پیامد قطع آن روشن نیست، کار را شروع نکنید و از مسئول فنی کمک بگیرید."},{"id":"section-2","title":"قطع و ایمن‌سازی را تأیید کنید","content":"روش قطع، قفل‌گذاری و برچسب‌گذاری باید طبق دستورالعمل محل کار انجام شود تا وصل ناخواسته رخ ندهد. بی‌برق‌بودن را با روش و ابزار تأییدشده و توسط فرد واجد صلاحیت بررسی کنید؛ خاموش‌بودن یک کلید به‌تنهایی کافی نیست."},{"id":"section-3","title":"ابزار و حفاظت فردی","content":"ابزار، پراب و تجهیزات حفاظت فردی باید متناسب با سطح خطر، محیط و ردهٔ کاری باشند و پیش از استفاده بازبینی شوند. ابزار ترک‌خورده، آلوده یا فاقد مشخصات لازم را کنار بگذارید. محدودهٔ کار را مرتب و افراد غیرمرتبط را دور نگه دارید."},{"id":"section-4","title":"بازبینی و بازگردانی","content":"پیش از بستن تابلو، اتصال‌ها، پوشش‌ها و نبود ابزار یا قطعهٔ جا‌مانده را کنترل کنید. قفل‌ها فقط توسط افراد مجاز و مطابق فرایند محل برداشته شوند. پس از بازگردانی برق، وضعیت را از فاصلهٔ ایمن پایش و نتیجهٔ کار را ثبت کنید."}],"conclusion":"برای تابلو برق، فرایند ایمن و فرد آموزش‌دیده اصل کار است. این متن جای دستورالعمل رسمی، ارزیابی خطر یا استانداردهای لازم محل کار را نمی‌گیرد.","sources":[],"tags":[{"label":"تابلو برق","filter":"area-electrical"},{"label":"چک‌لیست ایمنی","filter":"safety"}],"relatedArticles":[],"metrics":{"views":0,"likes":0,"averageRating":0,"comments":0}}},
      {"branch":"education","topic":"tools","area":"workshop","readMinutes":5,"article":{"slug":"workbench-task-light-placement","category":"آموزش تخصصی","kicker":"چیدمان کارگاه","title":"چراغ کار را روی میز تعمیر چطور جانمایی کنیم؟","summary":"زاویهٔ تابش، سایهٔ دست، خیرگی و رنگ سطح روی دید کار دقیق اثر می‌گذارند؛ جای چراغ را با آزمون عملی تنظیم کنید.","author":"تحریریه ندا اولیائی","publishedAt":"۱۴۰۵/۰۸/۰۵","readTime":"۵ دقیقه مطالعه","heroImage":"content/products/images/main/led-work-light-with-stand-hn-019-row-019-main.webp","contentImage":"content/products/images/main/led-work-light-with-stand-hn-019-row-019-main.webp","lead":"چراغ پرنور اگر در جای نامناسب باشد می‌تواند سایه یا بازتاب آزاردهنده بسازد. چیدمان را از محل واقعی انجام کار شروع کنید.","sections":[{"id":"section-1","title":"از جهت غالب کار شروع کنید","content":"اگر راست‌دست هستید، قرارگرفتن منبع نور در سمت چپ و کمی جلوتر معمولاً سایهٔ دست را کمتر می‌کند؛ برای چپ‌دست‌ها برعکس را امتحان کنید. این یک نقطهٔ شروع است و شکل میز و ابزار ممکن است نتیجه را تغییر دهد."},{"id":"section-2","title":"تابش مستقیم و بازتاب را کم کنید","content":"نور را طوری تنظیم کنید که مستقیم به چشم نتابد و از سطح براق قطعه به سمت دید شما بازنگردد. تغییر چند درجه‌ای زاویه یا جابه‌جایی چراغ می‌تواند بازتاب را کم کند. در کار ظریف، نور پخش‌شده را با نور موضعی ترکیب کنید."},{"id":"section-3","title":"ارتفاع و پایداری پایه","content":"ارتفاع منبع را با اندازهٔ قطعه و محدودهٔ حرکت دست تنظیم کنید؛ چراغ نباید با ابزار برخورد کند یا در مسیر جابه‌جایی باشد. پایه باید روی سطح ثابت بماند و کابل آن از لبهٔ تیز و مسیر رفت‌وآمد دور شود."},{"id":"section-4","title":"در محل کار آزمایش کنید","content":"چراغ را با همان قطعه و عملیات واقعی امتحان کنید و سایه، یکنواختی نور و خستگی چشم را بسنجید. اگر کار روی سطوح متفاوت انجام می‌شود، پایهٔ قابل تنظیم یا چند منبع با شدت کنترل‌پذیر انعطاف بیشتری می‌دهد."}],"conclusion":"محل چراغ را با توجه به دست غالب، بازتاب سطح و نوع جزئیات تنظیم کنید. کیفیت نور را در همان میز و شرایطی بسنجید که قرار است کار در آن انجام شود.","sources":[],"tags":[{"label":"نور کارگاهی","filter":"area-workshop"},{"label":"میز تعمیر","filter":"area-workshop"}],"relatedArticles":[],"metrics":{"views":0,"likes":0,"averageRating":0,"comments":0}}},
      {"branch":"buying","topic":"tools","area":"workshop","readMinutes":5,"article":{"slug":"choosing-hot-air-rework-station","category":"راهنمای خرید","kicker":"راهنمای تجهیزات تعمیر برد","title":"برای تعمیر برد ایستگاه هوای گرم انتخاب کنیم یا هویه؟","summary":"نوع قطعه، کنترل دما و جریان هوا، نازل‌ها و تهویه مشخص می‌کنند کدام ابزار برای میز تعمیر شما مناسب‌تر است.","author":"تحریریه ندا اولیائی","publishedAt":"۱۴۰۵/۰۸/۰۶","readTime":"۵ دقیقه مطالعه","heroImage":"content/products/images/main/hot-air-rework-station-hn-013-row-013-main.webp","contentImage":"content/products/images/main/hot-air-rework-station-hn-013-row-013-main.webp","lead":"هویه و ایستگاه هوای گرم کاربردهای هم‌پوشان اما متفاوت دارند. انتخاب به قطعه، دسترسی و مهارت کاربر بستگی دارد، نه صرفاً بیشینهٔ توان دستگاه.","sections":[{"id":"section-1","title":"نوع تعمیر را تعریف کنید","content":"برای اتصال‌های نقطه‌ای و قطعات پایه‌دار، هویه با نوک مناسب می‌تواند کنترل خوبی بدهد. قطعات نصب سطحی یا کارهایی که نیاز به گرم‌کردن یکنواخت ناحیه دارند ممکن است از هوای گرم سود ببرند. پیش از انتخاب، چند کار پرتکرار خود را فهرست کنید."},{"id":"section-2","title":"کنترل دما و جریان هوا","content":"نمایشگر و امکان تنظیم، زمانی مفید است که رفتار دستگاه پایدار و قابل تکرار باشد. بازهٔ دما یا عدد روی نمایشگر به‌تنهایی کیفیت را تضمین نمی‌کند؛ طراحی دسته، پاسخ دستگاه و دستورالعمل سازنده را هم بررسی کنید. جریان بیش از حد می‌تواند قطعات مجاور را جابه‌جا کند."},{"id":"section-3","title":"نازل، پایه و متعلقات","content":"تنوع نازل باید با ابعاد قطعات و فضای اطراف آن‌ها متناسب باشد. محل قرارگیری دسته، پایهٔ ایمن و دسترسی به قطعات مصرفی را در نظر بگیرید. محتویات جعبه و امکان تهیهٔ نازل جایگزین را پیش از خرید روشن کنید."},{"id":"section-4","title":"تهویه و نگهداری میز","content":"گرم‌کردن مواد لحیم‌کاری می‌تواند بخار ایجاد کند؛ تهویهٔ موضعی مناسب و فاصلهٔ امن از مواد قابل اشتعال را در برنامهٔ میز بگنجانید. پس از کار، دستگاه را روی پایه بگذارید تا طبق دستور سازنده خنک شود و مسیر هوا مسدود نماند."}],"conclusion":"برای کارهای ترکیبی، ممکن است هر دو ابزار لازم باشند؛ برای شروع، نوع قطعات و تعمیرات پرتکرار را معیار قرار دهید و تهویه و فضای ایمن را بخشی از هزینه و چیدمان بدانید.","sources":[],"tags":[{"label":"هوای گرم","filter":"area-workshop"},{"label":"تعمیر برد","filter":"area-workshop"}],"relatedArticles":[],"metrics":{"views":0,"likes":0,"averageRating":0,"comments":0}}},
      {"branch":"safety","topic":"tools","area":"tools","readMinutes":5,"article":{"slug":"power-tool-battery-storage","category":"ایمنی و نگهداری","kicker":"نگهداری تجهیزات شارژی","title":"باتری ابزار شارژی را در کارگاه درست نگهداری کنید","summary":"دما، رطوبت، ضربه و وضعیت شارژ بر سلامت باتری اثر می‌گذارند؛ توصیهٔ دقیق هر مدل را از سازنده دنبال کنید.","author":"تحریریه ندا اولیائی","publishedAt":"۱۴۰۵/۰۸/۰۷","readTime":"۵ دقیقه مطالعه","heroImage":"content/products/images/main/rechargeable-inspection-light-hn-018-row-018-main.webp","contentImage":"content/products/images/main/rechargeable-inspection-light-hn-018-row-018-main.webp","lead":"باتری سالم هم اگر در محیط نامناسب بماند یا آسیب ببیند می‌تواند خطرساز شود. نگهداری را بر اساس نوع باتری و راهنمای همان سازنده انجام دهید.","sections":[{"id":"section-1","title":"محیط خشک و دمای متعادل","content":"باتری را دور از تابش مستقیم، منبع گرما، رطوبت و مواد خورنده نگه دارید. محدودهٔ مجاز دما در همهٔ مدل‌ها یکسان نیست؛ راهنمای سازنده را بخوانید و باتری بسیار سرد یا داغ را تا رسیدن به شرایط مجاز شارژ نکنید."},{"id":"section-2","title":"از ضربه و اتصال کوتاه جلوگیری کنید","content":"باتری را در جعبه یا محفظه‌ای نگه دارید که در برابر ضربه و تماس با قطعات فلزی محافظت شود. ترمینال‌ها را با ابزار یا کلیدهای کارگاه در تماس نگذارید. باتری متورم، ترک‌خورده، نشتی‌دار یا بیش از حد گرم را استفاده یا شارژ نکنید."},{"id":"section-3","title":"شارژ و انبارش بلندمدت","content":"برای شارژ از شارژر سازگار با همان خانوادهٔ باتری استفاده کنید و تهویهٔ اطراف آن را نبندید. سطح شارژ مناسب برای نگهداری طولانی را از دستور سازنده بررسی کنید؛ توصیهٔ عمومی برای همهٔ شیمی‌ها و مدل‌ها یکسان نیست. وضعیت باتری‌های ذخیره را دوره‌ای کنترل کنید."},{"id":"section-4","title":"پایان عمر باتری","content":"باتری فرسوده را در زبالهٔ معمولی یا آتش نیندازید. ترمینال‌ها را طبق دستورالعمل محلی در برابر اتصال کوتاه ایمن کنید و آن را به مسیر جمع‌آوری باتری یا پسماند الکترونیکی بسپارید. باتری آسیب‌دیده را جدا از مواد قابل اشتعال نگه دارید و برای دفع از راهنمای تخصصی کمک بگیرید."}],"conclusion":"محیط مناسب، شارژر سازگار و بازرسی منظم به افزایش عمر و کاهش خطر کمک می‌کند. دستور سازنده و مقررات دفع محلی برای هر باتری اولویت دارند.","sources":[],"tags":[{"label":"باتری شارژی","filter":"area-tools"},{"label":"نگهداری ابزار","filter":"safety"}],"relatedArticles":[],"metrics":{"views":0,"likes":0,"averageRating":0,"comments":0}}},
      {"branch":"education","topic":"tools","area":"tools","readMinutes":5,"article":{"slug":"drill-concrete-anchor-holes","category":"آموزش تخصصی","kicker":"آموزش سوراخ‌کاری","title":"برای سوراخ‌کاری بتن، مته و حالت دریل را درست انتخاب کنید","summary":"جنس سطح، قطر رول‌پلاک، نوع سه‌نظام و وضعیت چکشی را پیش از سوراخ‌کاری بتن هماهنگ کنید.","author":"تحریریه ندا اولیائی","publishedAt":"۱۴۰۵/۰۸/۰۸","readTime":"۵ دقیقه مطالعه","heroImage":"content/products/images/main/electric-hammer-drill-hn-003-row-003-main.webp","contentImage":"content/products/images/main/electric-hammer-drill-hn-003-row-003-main.webp","lead":"سوراخ تمیز در بتن به متهٔ سالم، ابزار سازگار و کنترل گردوغبار نیاز دارد. پیش از شروع، از نبود کابل و لوله در مسیر مطمئن شوید.","sections":[{"id":"section-1","title":"قطر و عمق را از اتصال بگیرید","content":"قطر مته را با مشخصات رول‌پلاک یا مهار مورد استفاده هماهنگ کنید و عمق لازم را از راهنمای آن بخوانید. سوراخ خیلی بزرگ یا کم‌عمق باعث اتصال نامطمئن می‌شود. برای عمق‌های تکراری، محدودکنندهٔ عمق کمک می‌کند نتیجه یکنواخت بماند."},{"id":"section-2","title":"مته و سه‌نظام سازگار","content":"متهٔ مخصوص مصالح یا بتن را بر اساس نوع دستگاه و سه‌نظام انتخاب کنید. متهٔ کند یا آسیب‌دیده فشار و گرمای بیشتری ایجاد می‌کند و کیفیت سوراخ را پایین می‌آورد. قبل از نصب، ساق مته و قفل‌شدن آن در سه‌نظام را بررسی کنید."},{"id":"section-3","title":"حالت کار و کنترل ابزار","content":"حالت چکشی فقط زمانی به‌کار می‌آید که دستگاه، مته و سطح برای آن طراحی شده باشند. دستگاه را محکم و با دو دست، در وضعیت بدنی پایدار نگه دارید و اجازه دهید مته کار کند؛ فشار افراطی به موتور و مته آسیب می‌زند."},{"id":"section-4","title":"ایمنی، گردوغبار و پایان کار","content":"مسیر پنهان کابل و لوله را پیش از سوراخ‌کاری بررسی کنید و از حفاظت چشم، شنوایی و کنترل گردوغبار متناسب با محیط استفاده کنید. پس از توقف کامل، مته را خارج و سوراخ را با روش مناسب تمیز کنید تا مهار درست بنشیند."}],"conclusion":"متهٔ مناسب، عمق و قطر مشخص و ابزار سالم، پایهٔ اتصال قابل‌اعتماد هستند. اگر از مسیر تأسیسات یا جنس دیوار مطمئن نیستید، سوراخ‌کاری را تا بررسی متوقف کنید.","sources":[],"tags":[{"label":"دریل چکشی","filter":"area-tools"},{"label":"بتن","filter":"area-tools"}],"relatedArticles":[],"metrics":{"views":0,"likes":0,"averageRating":0,"comments":0}}},
      {"branch":"buying","topic":"tools","area":"electrical","readMinutes":5,"article":{"slug":"choosing-voltage-tester","category":"راهنمای خرید","kicker":"انتخاب ابزار سنجش برق","title":"تستر ولتاژ غیرتماسی را برای چه کاری بخریم؟","summary":"تستر غیرتماسی برای بررسی اولیه مفید است، اما کاربرد، محدوده و محدودیت آن باید پیش از خرید روشن باشد.","author":"تحریریه ندا اولیائی","publishedAt":"۱۴۰۵/۰۸/۰۹","readTime":"۵ دقیقه مطالعه","heroImage":"content/products/images/main/non-contact-voltage-tester-hn-027-row-027-main.webp","contentImage":"content/products/images/main/non-contact-voltage-tester-hn-027-row-027-main.webp","lead":"تستر غیرتماسی وجود میدان الکتریکی را در شرایط مشخص آشکار می‌کند؛ نتیجهٔ آن به‌تنهایی برای اثبات بی‌برقی کافی نیست.","sections":[{"id":"section-1","title":"کاربرد و محدوده را مشخص کنید","content":"مدل‌های مختلف برای محدوده‌ها و محیط‌های متفاوت ساخته می‌شوند. ولتاژ کاری، نوع مدار، نشانگر دیداری یا شنیداری و شرایط محیطی را از مشخصات رسمی دستگاه بررسی کنید. ابزار را با محل واقعی استفاده تطبیق دهید."},{"id":"section-2","title":"نحوهٔ هشدار را مقایسه کنید","content":"نمایشگر LED، بوق و چراغ وضعیت در محیط‌های پرنور یا پرصدا تجربهٔ متفاوتی دارند. حساسیت قابل تنظیم ممکن است تشخیص را آسان کند، اما حساسیت بالاتر احتمال هشدار ناشی از میدان مجاور را هم افزایش می‌دهد. طراحی دکمه و گیرهٔ حمل را نیز بسنجید."},{"id":"section-3","title":"محدودیت سنجش غیرتماسی","content":"عایق کابل، فاصله، جهت قرارگیری، میدان‌های مجاور و وضعیت باتری می‌توانند روی پاسخ اثر بگذارند. نبود هشدار، بی‌برقی را ثابت نمی‌کند و هشدار نیز جای سنجش تأییدی را نمی‌گیرد. دستورالعمل محل کار برای تشخیص ولتاژ را مبنا بگذارید."},{"id":"section-4","title":"بازبینی و نگهداری","content":"پیش از هر بار استفاده، بدنه، نشانگر و باتری را بررسی و عملکرد را طبق دستور سازنده کنترل کنید. اگر ابزار افتاده، خیس یا آسیب‌دیده است، نتیجهٔ آن را قابل اتکا فرض نکنید تا بررسی شود. باتری کم‌توان می‌تواند هشدار را مختل کند."}],"conclusion":"تستر غیرتماسی ابزار بررسی اولیه است. هنگام خرید، محدوده و شیوهٔ هشدار را با کاربرد تطبیق دهید و برای تصمیم ایمنی از روش تأییدی مناسب و فرد واجد صلاحیت کمک بگیرید.","sources":[],"tags":[{"label":"تستر ولتاژ","filter":"area-electrical"},{"label":"ایمنی برق","filter":"safety"}],"relatedArticles":[],"metrics":{"views":0,"likes":0,"averageRating":0,"comments":0}}},
      {"branch":"safety","topic":"tools","area":"workshop","readMinutes":5,"article":{"slug":"soldering-fume-extraction","category":"ایمنی و نگهداری","kicker":"ایمنی میز تعمیر","title":"تهویهٔ موضعی میز لحیم‌کاری را بهتر تنظیم کنید","summary":"مکش نزدیک محل تولید دود، مسیر هوای درست و نگهداری فیلترها به کاهش پخش آلاینده در فضای کار کمک می‌کند.","author":"تحریریه ندا اولیائی","publishedAt":"۱۴۰۵/۰۸/۱۰","readTime":"۵ دقیقه مطالعه","heroImage":"content/products/images/main/bench-soldering-station-hn-014-row-014-main.webp","contentImage":"content/products/images/main/bench-soldering-station-hn-014-row-014-main.webp","lead":"تهویهٔ عمومی اتاق همیشه دود لحیم‌کاری را در نقطهٔ تولید جمع نمی‌کند. راهکار موضعی باید بدون مزاحمت برای کار، جریان را از ناحیهٔ تنفس دور کند.","sections":[{"id":"section-1","title":"مکش را نزدیک منبع بگذارید","content":"دهانهٔ مکش را نزدیک محل لحیم‌کاری قرار دهید، اما آن‌قدر نزدیک نباشد که کار دست یا دید را مختل کند. دود باید از مسیر تنفس کاربر دور شود و وارد فیلتر یا خروجی طراحی‌شده گردد؛ دمیدن دود در فضا، تهویه محسوب نمی‌شود."},{"id":"section-2","title":"مسیر هوا و ظرفیت دستگاه","content":"کشش هوا را با نگه‌داشتن دود در محدودهٔ مکش بررسی کنید، نه فقط صدای فن یا عدد روی جعبه. اگر چند میز هم‌زمان استفاده می‌شوند، ظرفیت سامانه و طول کانال اهمیت پیدا می‌کند. راهنمای دستگاه، فاصلهٔ نصب و مسیر خروجی را مشخص می‌کند."},{"id":"section-3","title":"فیلتر را درست انتخاب و سرویس کنید","content":"فیلتر باید برای آلاینده و روش گردش هوا مناسب باشد؛ هر فیلتر همهٔ مواد را حذف نمی‌کند. زمان تعویض، جهت نصب و نحوهٔ دفع را از سازنده پیگیری کنید. فیلتر اشباع یا نصب اشتباه می‌تواند جریان را کم کند و حس کاذب ایمنی بدهد."},{"id":"section-4","title":"رفتار کاری را هم اصلاح کنید","content":"از داغ‌کردن غیرضروری، ماندن طولانی سر روی قطعه و مواد ناشناخته پرهیز کنید. میز را تمیز نگه دارید و تهویه را هنگام کار فعال کنید. اگر بو، تحریک یا دود در محیط باقی می‌ماند، کار را متوقف کنید و علت را بررسی کنید."}],"conclusion":"مکش نزدیک منبع، فیلتراسیون سازگار و سرویس به‌موقع باید با هم کار کنند. انتخاب تهویه را با ماهیت مواد و ارزیابی خطر محل هماهنگ کنید.","sources":[],"tags":[{"label":"تهویه میز لحیم‌کاری","filter":"area-workshop"},{"label":"ایمنی کارگاه","filter":"safety"}],"relatedArticles":[],"metrics":{"views":0,"likes":0,"averageRating":0,"comments":0}}},
      {"branch":"education","topic":"tools","area":"electrical","readMinutes":5,"article":{"slug":"continuity-testing-correctly","category":"آموزش تخصصی","kicker":"آموزش اندازه‌گیری","title":"تست پیوستگی را بدون خطا انجام دهید","summary":"آماده‌سازی مدار، جبران مقاومت پراب و فهم صدای بوق از نکات مهم آزمون پیوستگی است.","author":"تحریریه ندا اولیائی","publishedAt":"۱۴۰۵/۰۸/۱۱","readTime":"۵ دقیقه مطالعه","heroImage":"content/products/images/main/circuit-continuity-tester-hn-029-row-029-main.webp","contentImage":"content/products/images/main/circuit-continuity-tester-hn-029-row-029-main.webp","lead":"بوق پیوستگی نتیجه‌ای ساده به نظر می‌رسد، اما مدار موازی یا قطعهٔ باقی‌مانده می‌تواند تفسیر آن را تغییر دهد.","sections":[{"id":"section-1","title":"مدار را بی‌برق کنید","content":"پیوستگی را روی مدار برقدار اندازه نگیرید. منبع را طبق روش ایمن جدا کنید و انرژی ذخیره‌شده را در نظر بگیرید. در مدارهای حساس، دستورالعمل سازندهٔ دستگاه یا برد را پیش از اتصال پراب‌ها بخوانید."},{"id":"section-2","title":"خود پراب‌ها را بررسی کنید","content":"دو نوک پراب را به هم بزنید و مقدار یا صدای مرجع را ببینید. مقاومت سیم‌ها و تماس پراب می‌تواند در اندازه‌گیری کم‌اهم اثر بگذارد؛ برخی دستگاه‌ها قابلیت صفرکردن آن را دارند. اتصال لق یا نوک فرسوده نتیجهٔ ناپایدار می‌دهد."},{"id":"section-3","title":"آستانهٔ بوق را بشناسید","content":"بوق در بسیاری از مدل‌ها فقط نشان می‌دهد مقاومت از آستانه‌ای پایین‌تر است و الزاماً اتصال ایده‌آل را ثابت نمی‌کند. برای مقایسهٔ اتصال‌ها، عدد مقاومت را هم ببینید و مشخصات آستانهٔ دستگاه خود را مطالعه کنید."},{"id":"section-4","title":"مسیر موازی را در نظر بگیرید","content":"قطعات متصل در مدار می‌توانند مسیر جایگزین بسازند و بوق ایجاد کنند، حتی وقتی مسیر موردنظر باز است. اگر نتیجه مبهم است، روش جداسازی مناسب را با رعایت دستورالعمل تعمیر انتخاب کنید و فقط یک سنجش را مبنای تشخیص نگذارید."}],"conclusion":"آزمون پیوستگی زمانی معنی‌دار است که مدار بی‌برق، پراب سالم و مسیر اندازه‌گیری شناخته‌شده باشد. آستانهٔ بوق و مسیرهای موازی را همیشه در تفسیر نتیجه لحاظ کنید.","sources":[],"tags":[{"label":"پیوستگی","filter":"area-electrical"},{"label":"مولتی‌متر","filter":"area-electrical"}],"relatedArticles":[],"metrics":{"views":0,"likes":0,"averageRating":0,"comments":0}}},
      {"branch":"buying","topic":"tools","area":"workshop","readMinutes":5,"article":{"slug":"choosing-work-light-color","category":"راهنمای خرید","kicker":"راهنمای نورپردازی","title":"چراغ کارگاه را بر اساس رنگ نور انتخاب کنیم؟","summary":"شار نوری، پخش نور، خیرگی و بازنمایی رنگ از عدد کلوین مهم‌ترند؛ انتخاب را با نوع کار و محیط بسنجید.","author":"تحریریه ندا اولیائی","publishedAt":"۱۴۰۵/۰۸/۱۲","readTime":"۵ دقیقه مطالعه","heroImage":"content/products/images/main/workshop-led-floodlight-hn-017-row-017-main.webp","contentImage":"content/products/images/main/workshop-led-floodlight-hn-017-row-017-main.webp","lead":"رنگ نور در برداشت بصری اثر دارد، اما به‌تنهایی روشنایی یا کیفیت یک چراغ را نشان نمی‌دهد. مشخصات کامل و آزمون در محل تصمیم دقیق‌تری می‌دهد.","sections":[{"id":"section-1","title":"کلوین فقط رنگ ظاهری را توصیف می‌کند","content":"دمای رنگ هم‌بسته، حس گرم یا سرد نور سفید را توصیف می‌کند و معیار شدت روشنایی نیست. دو چراغ با کلوین مشابه ممکن است شار نوری، پخش یا کیفیت رنگ متفاوتی داشته باشند؛ بنابراین فقط با این عدد خرید نکنید."},{"id":"section-2","title":"شار و پخش نور را ببینید","content":"شار نوری کل خروجی چراغ را نشان می‌دهد، اما شکل پخش مشخص می‌کند چه مقدار نور روی میز یا سطح کار می‌رسد. زاویهٔ تابش و امکان تنظیم پایه را با فاصله و وسعت محل بسنجید. نور متمرکز ممکن است کنار سایه‌های تند ایجاد کند."},{"id":"section-3","title":"بازتاب و کیفیت رنگ","content":"برای تشخیص سیم‌ها، قطعات و رنگ پوشش‌ها، کیفیت بازنمایی رنگ اهمیت دارد. سطح براق می‌تواند بازتاب آزاردهنده بسازد و نور نامتوازن چشم را خسته کند. اگر مشخصهٔ بازنمایی رنگ اعلام نشده، از فروشنده دادهٔ رسمی محصول را بخواهید."},{"id":"section-4","title":"در همان کارگاه امتحان کنید","content":"چراغ را روی میز و در ارتفاع واقعی قرار دهید و یکنواختی، سایه و خیرگی را هنگام انجام کار بسنجید. دمای رنگی را انتخاب کنید که در استفادهٔ طولانی برای کاربر راحت باشد و با سایر چراغ‌های محیط تضاد آزاردهنده نداشته باشد."}],"conclusion":"برای انتخاب چراغ، ترکیب شار نوری، پخش، کیفیت رنگ و راحتی دید را بسنجید. عدد کلوین فقط یکی از مشخصه‌هاست و جای آزمون در محیط واقعی را نمی‌گیرد.","sources":[],"tags":[{"label":"چراغ کارگاهی","filter":"area-workshop"},{"label":"روشنایی","filter":"area-workshop"}],"relatedArticles":[],"metrics":{"views":0,"likes":0,"averageRating":0,"comments":0}}},
      {"branch":"safety","topic":"tools","area":"tools","readMinutes":5,"article":{"slug":"inspect-insulated-hand-tools","category":"ایمنی و نگهداری","kicker":"نگهداری ابزار دستی","title":"ابزار عایق‌دار را پیش از هر شیفت بازرسی کنید","summary":"ترک، بریدگی، آلودگی و تعمیر غیراصولی می‌توانند ویژگی‌های حفاظتی ابزار عایق‌دار را از بین ببرند.","author":"تحریریه ندا اولیائی","publishedAt":"۱۴۰۵/۰۸/۱۳","readTime":"۵ دقیقه مطالعه","heroImage":"content/products/images/main/insulated-electrician-tool-kit-hn-023-row-023-main.webp","contentImage":"content/products/images/main/insulated-electrician-tool-kit-hn-023-row-023-main.webp","lead":"بازرسی چشمی کوتاه کمک می‌کند ابزار معیوب پیش از ورود به محل کار شناسایی شود؛ اما جای آزمون تخصصی یا برنامهٔ نگهداری سازمان را نمی‌گیرد.","sections":[{"id":"section-1","title":"پوشش را از ابتدا تا انتها ببینید","content":"سطح عایق را از نظر ترک، بریدگی، فرورفتگی، سوختگی، تورم یا بخش‌های جداشده بررسی کنید. تمرکز را فقط روی دسته نگذارید؛ محل اتصال ساق و بخش نزدیک نوک نیز مهم است. اگر عیب مشهود است، ابزار را استفاده نکنید."},{"id":"section-2","title":"آلودگی و آثار تعمیر","content":"روغن، حلال یا آلودگی ناشناخته را طبق روش سازنده پاک کنید و از سنباده‌زدن یا پوشاندن آسیب با نوار خودداری کنید. تعمیر دستی می‌تواند مشخصات حفاظتی را نامعلوم کند. ابزار تغییرشکل‌داده یا تعمیرشده را برای ارزیابی از چرخه خارج کنید."},{"id":"section-3","title":"مشخصات و نگهداری","content":"نشان سازنده، ردهٔ کاربرد و وضعیت دورهٔ بازرسی را مطابق رویهٔ محل بررسی کنید. ابزار را جدا از قطعات تیز و مواد شیمیایی نگه دارید تا عایق صدمه نبیند. جعبه یا غلاف مناسب از آسیب هنگام حمل جلوگیری می‌کند."},{"id":"section-4","title":"ثبت و جایگزینی","content":"اگر آسیب دیدید، ابزار را علامت‌گذاری و از دسترس مصرف خارج کنید تا اشتباهی دوباره استفاده نشود. مطابق برنامهٔ سازمان، بازبینی یا جایگزینی را ثبت کنید. برای کار روی برق، تنها ابزار تأییدشده و فرد آموزش‌دیده مجاز است."}],"conclusion":"هر نشانهٔ آسیب، آلودگی حل‌نشده یا تعمیر نامعتبر دلیل توقف استفاده است. روش بازرسی و آزمون دوره‌ای را از مسئول ایمنی و سازنده پیگیری کنید.","sources":[],"tags":[{"label":"ابزار عایق‌دار","filter":"area-tools"},{"label":"بازرسی ابزار","filter":"safety"}],"relatedArticles":[],"metrics":{"views":0,"likes":0,"averageRating":0,"comments":0}}},
      {"branch":"education","topic":"tools","area":"tools","readMinutes":5,"article":{"slug":"soldering-tip-temperature-basics","category":"آموزش تخصصی","kicker":"آموزش لحیم‌کاری","title":"دمای هویه را بر اساس اتصال تنظیم کنید","summary":"دمای مناسب به آلیاژ، اندازهٔ اتصال، انتقال حرارت نوک و حساسیت قطعه وابسته است؛ یک عدد ثابت برای همهٔ کارها وجود ندارد.","author":"تحریریه ندا اولیائی","publishedAt":"۱۴۰۵/۰۸/۱۴","readTime":"۵ دقیقه مطالعه","heroImage":"content/products/images/main/adjustable-soldering-iron-hn-012-row-012-main.webp","contentImage":"content/products/images/main/adjustable-soldering-iron-hn-012-row-012-main.webp","lead":"دمای خیلی پایین یا بیش از حد بالا می‌تواند اتصال را دشوار و قطعه را آسیب‌پذیر کند. هدف، انتقال حرارت کافی در زمان کنترل‌شده است.","sections":[{"id":"section-1","title":"اتصال و مواد را بشناسید","content":"نوع لحیم، ابعاد پد، ضخامت پایه و حساسیت قطعه بر تنظیم کار اثر دارند. توصیهٔ سازندهٔ قطعه و مواد مصرفی را در اولویت بگذارید. مقدار روی نمایشگر دمای نوک را نشان می‌دهد و ممکن است با دمای واقعی محل اتصال تفاوت داشته باشد."},{"id":"section-2","title":"نوک متناسب و تمیز انتخاب کنید","content":"نوک باید به محل اتصال دسترسی داشته و سطح تماس کافی فراهم کند. نوک بسیار ظریف برای اتصال بزرگ گرما را کند منتقل می‌کند؛ نوک بیش از حد بزرگ هم کنترل را سخت می‌کند. تمیزکاری و قلع‌اندودکردن طبق دستور سازنده به انتقال حرارت پایدار کمک می‌کند."},{"id":"section-3","title":"زمان تماس را کوتاه و کنترل‌شده نگه دارید","content":"اتصال را با تماس هم‌زمان نوک با پد و پایه گرم کنید و لحیم را به محل گرم‌شده برسانید. نگه‌داشتن طولانی هویه، فشار زیاد یا افزودن لحیم بی‌رویه می‌تواند برد و قطعه را آسیب بزند. در صورت دشواری، علت را پیدا کنید و صرفاً دما را بالا نبرید."},{"id":"section-4","title":"نتیجه را ارزیابی کنید","content":"اتصال مناسب باید از نظر شکل، خیس‌شدن سطح و استحکام مطابق معیار کار باشد. آثار سوختگی، جداشدن پد یا اتصال مات و شکننده می‌تواند نشانهٔ فرایند نامناسب باشد. پس از هر تغییر تنظیم، ابتدا روی نمونهٔ کم‌ارزش تمرین کنید."}],"conclusion":"تنظیم را با نوع اتصال و مواد هماهنگ کنید و در زمان تماس، نوک و تهویه دقت داشته باشید. برای قطعات حساس، محدودیت حرارتی سازنده معیار اصلی است.","sources":[],"tags":[{"label":"هویه","filter":"area-tools"},{"label":"لحیم‌کاری","filter":"area-workshop"}],"relatedArticles":[],"metrics":{"views":0,"likes":0,"averageRating":0,"comments":0}}},
      {"branch":"buying","topic":"tools","area":"tools","readMinutes":5,"article":{"slug":"choosing-electrician-tool-kit","category":"راهنمای خرید","kicker":"راهنمای خرید ابزار","title":"جعبه‌ابزار برق‌کار را بر اساس کار روزانه ببندید","summary":"ابزارهای پرتکرار، ردهٔ حفاظتی، کیفیت کیف و امکان جایگزینی قطعات را پیش از خرید مجموعه بررسی کنید.","author":"تحریریه ندا اولیائی","publishedAt":"۱۴۰۵/۰۸/۱۵","readTime":"۵ دقیقه مطالعه","heroImage":"content/products/images/main/electrician-tool-bag-set-hn-025-row-025-main.webp","contentImage":"content/products/images/main/electrician-tool-bag-set-hn-025-row-025-main.webp","lead":"یک مجموعهٔ بزرگ الزاماً مجموعهٔ کامل‌تری نیست. ترکیب ابزار باید با وظایف روزانه و الزامات ایمنی محل کار هماهنگ باشد.","sections":[{"id":"section-1","title":"فهرست کارهای معمول را تهیه کنید","content":"کارهای نصب، تعمیر، اندازه‌گیری و نگهداری خود را مرور کنید و ابزار لازم برای هرکدام را بنویسید. این کار کمک می‌کند هزینه صرف اقلام کم‌مصرف نشود و ابزار ضروری جا نماند. اندازه و وزن مجموعه را با شیوهٔ حمل روزانه بسنجید."},{"id":"section-2","title":"کیفیت اقلام مهم را جداگانه ببینید","content":"نام و مشخصات هر ابزار را بخوانید؛ به‌خصوص برای ابزار عایق‌دار و تجهیزات اندازه‌گیری. یک کیف ممکن است ابزارهایی با سطح کیفیت متفاوت داشته باشد. امکان تهیهٔ جداگانهٔ قلم‌های مصرفی و جایگزینی ابزار آسیب‌دیده را بررسی کنید."},{"id":"section-3","title":"چیدمان و دوام کیف","content":"محفظه‌های جدا، قفل مناسب و دسترسی سریع در محل کار صرفه‌جویی زمانی ایجاد می‌کند. دوخت، زیپ، دسته و تحمل وزن را با شرایط حمل بسنجید. کیف باید ابزار را نگه دارد و مانع برخورد نوک‌ها یا تماس ترمینال باتری با فلز شود."},{"id":"section-4","title":"محتویات و شرایط فروش را تأیید کنید","content":"فهرست اقلام داخل بسته را با صفحهٔ محصول و اقلام تحویلی تطبیق دهید. مدل دقیق، تعداد، لوازم جانبی و ضمانت را پیش از ثبت سفارش کنترل کنید. عکس مجموعه ممکن است نمایش اقلامی باشد که در بستهٔ اصلی وجود ندارند."}],"conclusion":"مجموعه‌ای را انتخاب کنید که اقلام پرتکرار، مشخصات ایمنی روشن و حمل مناسب داشته باشد. فهرست بسته‌بندی و امکان تأمین ابزار جایگزین را پیش از سفارش تأیید کنید.","sources":[],"tags":[{"label":"جعبه‌ابزار برق‌کار","filter":"area-tools"},{"label":"راهنمای خرید","filter":"buying"}],"relatedArticles":[],"metrics":{"views":0,"likes":0,"averageRating":0,"comments":0}}}
    ]';

    IF ISJSON(@NewArticles) <> 1
        THROW 51051, 'The new magazine article payload is invalid JSON.', 1;

    DECLARE @Pending TABLE ([Ordinal] INT PRIMARY KEY, [ArticleJson] NVARCHAR(MAX) NOT NULL);
    INSERT INTO @Pending ([Ordinal], [ArticleJson])
    SELECT CONVERT(INT, [key]), [value]
    FROM OPENJSON(@NewArticles);

    DECLARE @ArticleJson NVARCHAR(MAX);
    WHILE EXISTS (SELECT 1 FROM @Pending)
    BEGIN
        SELECT TOP (1) @ArticleJson = [ArticleJson] FROM @Pending ORDER BY [Ordinal];

        UPDATE [Store].[RuntimeDataset]
        SET [PayloadJson] = JSON_MODIFY([PayloadJson], 'append $.articles', JSON_QUERY(@ArticleJson)),
            [UpdatedAtUtc] = SYSUTCDATETIME()
        WHERE [DatasetKey] = N'magazine';

        DELETE FROM @Pending WHERE [ArticleJson] = @ArticleJson;
    END;

    INSERT INTO [Store].[SchemaMigration] ([MigrationKey]) VALUES (N'020-magazine-editorial-content');
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
